test("person timeline scenario 3", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "terms", "10");
  await ui.setSetting(pg_uma, "late-pct", "10.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-05");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "cap", "5.00");
  await ui.setSetting(pg_uma, "proof-threshold", "3.00");
  expect(await ui.setRole(pg_uma, "vic", "viewer")).toBe(true);
  await ui.setSetting(pg_uma, "grace-days", "3");
  await ui.setSetting(pg_uma, "note-threshold", "2.50");
  await ui.setSetting(pg_uma, "entry-date", "2026-03-01");
  expect(await ui.addHoliday(pg_uma, "2026-03-16")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "late")).toBe(true);
  expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "20.00", "note": "tpl"})).toBe(true);
  expect(await ui.setSettingDated(pg_uma, "rounding", "half-even", "2026-03-01", "half-even")).toBe(true);
  await ui.setSetting(pg_uma, "review-threshold", "4.00");
  await ui.setSetting(pg_uma, "review-sla", "5");
  await ui.setSetting(pg_uma, "default-grade", "C");
  await ui.setSetting(pg_uma, "max-open", "1");
  expect(await ui.addGrade(pg_uma, "D")).toBe(true);
  await ui.setSetting(pg_uma, "perm-today", "clerk");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50", "from": "2026-03-16"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B", "contact": "ben@x", "tags": "b, a"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B", "tags": "c"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "contact": "ADA@X"}));
  const pl_cam_1 = ui.must(await ui.addPlan(pg_uma, p_cam, {"amount": "7.77", "start": "2026-02-20", "end": "2026-04-30", "every": "10"}));
  expect(await ui.generatePlans(pg_uma)).toBe(2);
  const c_cam_0 = await ui.claimAt(pg_uma, p_cam, 0);
  const c_cam_1 = await ui.claimAt(pg_uma, p_cam, 1);
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  await ui.setSetting(pg_uma, "note-threshold", "1.00");
  expect(await ui.addLine(pg_uma, c_cam_1, {"label": "y", "qty": "3", "unit": "2.50"})).toBe(true);
  expect(await ui.claimAction(pg_uma, c_cam_1, "open")).toBe(true);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.reassign(pg_wes, c_cam_0, "Ben")).toBe(true);
  expect(await ui.claimAction(pg_wes, c_cam_1, "settle")).toBe(true);
  await ui.refresh(pg_wes);
  const c_cam_2 = ui.must(await ui.addClaim(pg_wes, p_cam, {"amount": "12.50", "date": "2026-03-05", "note": "n", "ref": "R-2", "tags": "b,a,a"}));
  expect(await ui.bulkVoid(pg_wes, [c_cam_2, c_cam_0], "dup")).toEqual({ voided: 2, refused: 0 });
  expect(await ui.addClaim(pg_wes, p_cam, {"amount": "-10.25", "corrects": "X-1"})).toBeNull();
  expect(await ui.addPatron(pg_wes, p_ben, "Cam")).toBe(true);
  expect(await ui.addNote(pg_wes, "hi")).toBe(true);
  expect(await ui.planPause(pg_wes, pl_cam_1, false)).toBe(false);
  const c_ben_1 = ui.must(await ui.addClaim(pg_wes, p_ben, {"amount": "4.00", "date": "2026-02-25", "note": "n", "ref": " r-1 "}));
  await ui.refresh(pg_wes);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.claimAction(pg_vic, c_ben_1, "open")).toBe(false);
  expect(await ui.statement(pg_vic, p_ada)).toBe(false);
  expect(await ui.editClaim(pg_vic, c_ben_1, {"amount": "4.00"})).toBe(false);
  await ui.refresh(pg_wes);
  expect(await ui.unstate(pg_wes, p_cam)).toBe(true);
  expect(await ui.snapshotCompare(pg_wes, "2026-03-20", "2026-04-05")).toEqual(["Ada", "Cam", "Ben"]);
  await ui.setAsOf(pg_wes, "2026-03-01");
  await ui.refresh(pg_wes);
  ]);
  await ui.clearAsOf(pg_wes);
  await ui.refresh(pg_wes);

